let sh;

function setup() {
	pixelDensity(2);
	createCanvas(1112, 834,WEBGL);
  sh = createShader(vert,frag);
	this.shader(sh);
	rectMode(CENTER);
}

function draw() {
	background(0);
	sh.setUniform("u_resolution", [width*2,height*2]);
	sh.setUniform("u_time", millis()*0.001);
	noStroke();

	rect(0,0,width,height);
}

// === Tab: Shader ===
var frag = `

#ifdef GL_ES
precision highp float;
#endif

#define PI 3.14159265358979323846

uniform vec2 u_resolution;
uniform float u_time;


float random (in vec2 st) {
		//return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);// < - not work on mobile
   	highp float a = 12.9898;
    highp float b = 58.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,2.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}


mat2 rotate2d(float angle){
    return mat2(cos(angle),-sin(angle),
                sin(angle),cos(angle));
}


float grid(in vec2 uv){
    float scale = 4.;
    uv *= scale;
    uv = fract(uv);
    float o = uv.x >0.99 && uv.x <= 1. || uv.y >0.99 && uv.y <= 1. ? 1.:0.;
    return o;
}

void main() {
		vec2 st = vec2(0.);
    st = gl_FragCoord.xy/u_resolution.x;

		vec2 symPos = vec2(0.);
    symPos = st;
    symPos.x = abs(st.x-0.5)*2.;
    symPos.y = abs(st.y-0.5*u_resolution.y/u_resolution.x)*2.3;
    symPos= symPos.x >symPos.y ? symPos.xy :symPos.yx;
    symPos =  rotate2d(u_time/10.) * (symPos);

		float nv = 0.;
    nv = noise((symPos + u_time/10.)*15.);
    nv = step(nv,.5+.15*sin(u_time/2.)) + random(st)*.3;

		vec3 color = vec3(0.);
    color = vec3(symPos.x*.1 + .1,0.2,symPos.y*.4 + .3) * vec3(1.-nv)  + vec3(nv)*.95 * vec3(1.800,0.527,0.998); 
    gl_FragColor = vec4(color,1.0);
}

`;


var vert=`
//standard vertex shader
#ifdef GL_ES
      precision highp float;
    #endif
		#extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

